'use client'
import { useEffect, useLayoutEffect, useRef, useState, type CSSProperties, type KeyboardEvent } from 'react'
import { Check, Trash2 } from 'lucide-react'

// A destructive action (revoke a key, disconnect a source) confirmed in the button itself, never in a dialog: the
// console's pixel hold (console2.css .v2-hold, version 1). Pressing and holding fills the button with the website's
// red 6px squares from the left over `ms`; each column carries a white copy of the label, so it turns as the squares
// land; the bin's lid lifts while held; letting go rewinds right to left in under 200ms; at the end the check draws
// and holds a beat before `onConfirm` is called. The label rolls up to "Hold" under the pointer. Space or Enter hold
// it from the keyboard. Re-key it to set it back if what it confirmed failed.
export interface HoldButtonProps { label: string, ms?: number, onConfirm?: () => void, className?: string }

const PX = 6
interface Grid { cols: number, w: number, h: number, cells: Array<Record<string, number>> }

export function HoldButton({ label, ms = 1000, onConfirm, className }: HoldButtonProps) {
  const root = useRef<HTMLButtonElement | null>(null)
  const [holding, setHolding] = useState(false)
  const [done, setDone] = useState(false)
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)
  const landing = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)
  const state = useRef({ holding: false, done: false, pointing: false })
  const confirm = useRef(onConfirm)
  confirm.current = onConfirm

  function finish() {
    state.current.done = true
    state.current.holding = false
    setDone(true)
    setHolding(false)
    // ds-latency: the check is seen before what it confirms happens; the press itself answered at once.
    landing.current = setTimeout(() => confirm.current?.(), 320)
  }
  function start() {
    if (state.current.done || state.current.holding) return
    state.current.holding = true
    setHolding(true)
    // ds-latency: the hold is the confirmation; its length is the point.
    timer.current = setTimeout(finish, ms)
  }
  function cancel() {
    clearTimeout(timer.current)
    state.current.holding = false
    setHolding(false)
  }
  // Safari takes focus off a button as it is pressed, so losing focus ends a hold only by keyboard.
  function press() { state.current.pointing = true; start() }
  function release() { state.current.pointing = false; cancel() }
  function onKeyDown(event: KeyboardEvent) {
    if (event.key !== ' ' && event.key !== 'Enter') return
    event.preventDefault()
    if (!event.repeat) start()
  }
  function onKeyUp(event: KeyboardEvent) {
    if (event.key === ' ' || event.key === 'Enter') cancel()
  }
  function blur() { if (!state.current.pointing) cancel() }
  useEffect(() => () => { clearTimeout(timer.current); clearTimeout(landing.current) }, [])

  // 6px cells across the button as measured, each lighting when the hold reaches its column, with a little scatter.
  // --d is the way in; --o the way out, right to left.
  const [grid, setGrid] = useState<Grid | null>(null)
  useLayoutEffect(() => {
    const el = root.current
    if (!el) return
    function lay() {
      if (!el) return
      const w = el.offsetWidth
      const h = el.offsetHeight
      setGrid((g) => {
        if (g?.w === w && g.h === h) return g
        const cols = Math.ceil(w / PX)
        const rows = Math.ceil(h / PX)
        return {
          cols,
          w,
          h,
          cells: Array.from({ length: cols * rows }, (_, k) => {
            const col = k % cols
            const scatter = ((k * 37) % 11) / 11
            const at = (col + scatter) / cols
            return { '--d': Math.round(at * ms * 0.94), '--o': Math.round((1 - at) * 120) }
          }),
        }
      })
    }
    lay()
    const ro = new ResizeObserver(lay)
    ro.observe(el)
    return () => ro.disconnect()
  }, [ms])
  const inks = grid ? Array.from({ length: grid.cols }, (_, c) => ({ col: grid.cells[c]!, ink: { width: `${grid.w}px`, height: `${grid.h}px`, transform: `translateX(${-c * PX}px)` } })) : []
  const verb = label.toLowerCase()
  const columns: CSSProperties | undefined = grid ? { gridTemplateColumns: `repeat(${grid.cols}, ${PX}px)` } : undefined

  return (
    <>
      <style href="ds-hold-button" precedence="ds">{css}</style>
      <button
        data-ds="hold-button"
        ref={root}
        type="button"
        className={className ? `ds-hold ${className}` : 'ds-hold'}
        data-holding={holding || undefined}
        data-done={done || undefined}
        aria-label={`hold to ${verb}`}
        onPointerDown={press}
        onPointerUp={release}
        onPointerLeave={release}
        onPointerCancel={release}
        onKeyDown={onKeyDown}
        onKeyUp={onKeyUp}
        onBlur={blur}
        onContextMenu={e => e.preventDefault()}
      >
        {grid && (
          <>
            <span className="ds-hold-px" aria-hidden="true" style={columns}>{grid.cells.map((c, k) => <i key={k} style={c} />)}</span>
            <span className="ds-hold-inks" aria-hidden="true" style={columns}>
              {inks.map((c, k) => <i key={k} style={c.col}><span className="ds-hold-ink" style={c.ink}><Trash2 size={12} strokeWidth={1.5} /><span className="ds-hold-word"><span className="invisible">{label}</span><span className="absolute inset-x-0">Hold</span></span></span></i>)}
            </span>
            <span className="ds-hold-done" aria-hidden="true"><Check size={12} strokeWidth={2} />Done</span>
          </>
        )}
        <span className="ds-hold-label"><Trash2 size={12} strokeWidth={1.5} aria-hidden="true" />
          <span className="ds-roll"><span className="ds-roll-a">{label}</span><span className="ds-roll-b" aria-hidden="true">Hold</span></span>
        </span>
      </button>
    </>
  )
}

export default HoldButton

